steps.script:
# Two user plans: the rich fixture unchanged (its Deffkilla -> Warbikers
# attachment is legal — the control), and a copy whose only change is an
# attachment the game cannot make: Wazdakka Gutsmek has no Leader ability.
var PV = load("res://scripts/PlanValidator.gd")
var PM = load("res://scripts/PlanManager.gd")
PM.ensure_user_plans_dir()
var dir = DirAccess.open("user://ai_plans")
if dir != null:
	dir.list_dir_begin()
	var f = dir.get_next()
	while f != "":
		if f.ends_with(".json"):
			dir.remove(f)
		f = dir.get_next()
	dir.list_dir_end()
var written = []
var plan = PV.load_plan_file("res://tests/fixtures/ai_plans/fixture_recon_stomps_rich.json")
for spec in [["", []], ["Fixture — impossible attachment", [{"character": "U_WAZDAKKA_GUTSMEK_A", "bodyguard": "U_WARBIKERS_A"}]]]:
	var copy = plan.duplicate(true)
	if str(spec[0]) != "":
		copy["name"] = str(spec[0])
		copy["deployment"]["attachments"] = spec[1]
	var path = "user://ai_plans/%s.json" % PM.slugify(str(copy.get("name", "")))
	var file = FileAccess.open(path, FileAccess.WRITE)
	if file != null:
		file.store_string(JSON.stringify(copy, "\t"))
		file.close()
		written.append(path.get_file())
written.sort()
return ",".join(written)

# The mutated plan really does warn, and the control really does not —
# asserted at the validator level first, so a browser failure below is a
# BROWSER failure and not a validator one.
var PV = load("res://scripts/PlanValidator.gd")
var alm = node.get_node("/root/ArmyListManager")
var army = alm.load_army_list("recon_stomps", 1)
var out = []
for src in ["user://ai_plans/fixture_recon_stomps_rich_all_five_verbs.json", "user://ai_plans/fixture_impossible_attachment.json"]:
	var r = PV.validate_plan(PV.load_plan_file(src), army)
	var att = 0
	for w in r["warnings"]:
		if str(w).begins_with("Attachment"):
			att += 1
	out.append("%s/%d" % [str(r["valid"]), att])
print("SCENARIO pm_f2 validator: control=%s mutated=%s" % [out[0], out[1]])
return "%s|%s" % [out[0], out[1]]

# The status column the player actually reads, for both rows. Rows are found
# by name — shipped plans sit in this list too.
var t = node.get_node("/root/MainMenu/PlanBrowserDialog/PlanBrowserRoot/PlanBrowserTree")
var found = {}
var item = t.get_root().get_first_child()
while item != null:
	found[item.get_text(0)] = item.get_text(4)
	item = item.get_next()
var bad = str(found.get("Fixture — impossible attachment", "MISSING"))
var ok = str(found.get("Fixture — Recon Stomps rich (all five verbs)", "MISSING"))
print("SCENARIO pm_f2 status column: impossible='%s' control='%s'" % [bad, ok])
return "%s|%s" % [bad, ok]

# Warning colour, not invalid — the plan stays usable; the AI falls back.
var t = node.get_node("/root/MainMenu/PlanBrowserDialog/PlanBrowserRoot/PlanBrowserTree")
var item = t.get_root().get_first_child()
while item != null:
	if item.get_text(0) == "Fixture — impossible attachment":
		var c = item.get_custom_color(4)
		var dlg = node.get_node("/root/MainMenu/PlanBrowserDialog")
		return "warn=%s invalid=%s" % [str(c == dlg.WARN_COLOR), str(c == dlg.INVALID_COLOR)]
	item = item.get_next()
return "row not found"

# Selecting the row must put the sentence in front of the player, naming the
# character and the rule — a bare count would not tell them what to change.
var dlg = node.get_node("/root/MainMenu/PlanBrowserDialog")
var t = node.get_node("/root/MainMenu/PlanBrowserDialog/PlanBrowserRoot/PlanBrowserTree")
var item = t.get_root().get_first_child()
while item != null:
	if item.get_text(0) == "Fixture — impossible attachment":
		item.select(0)
		t.item_selected.emit()
		break
	item = item.get_next()
var detail = str(dlg.detail_label.text)
var has_char = detail.find("U_WAZDAKKA_GUTSMEK_A") != -1
var has_rule = detail.find("no Leader ability") != -1
print("SCENARIO pm_f2 detail: %s" % detail.substr(0, 220))
return "char=%s rule=%s" % [str(has_char), str(has_rule)]

# Clean up: the fabricated plans must not leak into later scenarios.
var dir = DirAccess.open("user://ai_plans")
var removed = 0
if dir != null:
	for f in ["fixture_impossible_attachment.json", "fixture_recon_stomps_rich_all_five_verbs.json"]:
		if dir.file_exists(f):
			dir.remove(f)
			removed += 1
return removed
